/**
 * List.Item: one item: a title, with a leading mark, a description, a meta and a trailing control.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/list.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import {
  claimSlot,
  classes,
  createDerived,
  resolveSlot,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/list.module.css'

export interface ListItemProps {
  /**
   * The item whose page or detail is open. At most one per list. It has no effect on an item
   * that is only read, which has no link or button to say it to a screen reader.
   */
  current?: boolean
  /**
   * One supporting line under the title. It wraps and is never clipped.
   */
  description?: string
  /**
   * The item navigates: the title is a link whose target covers the row.
   */
  href?: string
  /**
   * One mark before the text: an Avatar, an Icon or an Image. Not a control.
   */
  leading?: JSX.Element
  /**
   * A short trailing fact the application has already formatted: a time, a count.
   */
  meta?: string
  /**
   * The app's router, on an item with an `href`, as on Link (`link.md` §Routing): a click that
   * would navigate this tab calls it in place of the browser.
   */
  onNavigate?: (href: string) => void
  /**
   * The item is picked. Without an `href` the title is a button whose target covers the row.
   * With one it is also called on every click of the link, one that opens a new tab included, so
   * a router uses `onNavigate` there.
   */
  onSelect?: () => void
  /**
   * The item's name, and the accessible name of its link or button.
   */
  title: string
  /**
   * One governed member after the text: a Badge, a Button, a Menu or a Switch. A control takes
   * its own press. A press on anything else in it is a press on the row.
   */
  trailing?: JSX.Element
}

/** List.Item: one item: a title, with a leading mark, a description, a meta and a trailing control. */
export default function ListItem(given: ListItemProps): JSX.Element {
  const props = mergeProps(
    { current: false } as Defaults<ListItemProps, 'current'>,
    claimSlot(given),
  )
  return scope(() => {
    const leadingSlot = resolveSlot(() => props.leading)
    const trailingSlot = resolveSlot(() => props.trailing)
    const navigatesHere = createDerived(
      () =>
        (event: MouseEvent): boolean =>
          !event.defaultPrevented &&
          event.button === 0 &&
          !event.metaKey &&
          !event.ctrlKey &&
          !event.shiftKey &&
          !event.altKey,
    )
    const route = createDerived(() => (event: MouseEvent): void => {
      if (
        props.href === undefined ||
        !(props.onNavigate !== undefined) ||
        !navigatesHere.value(event)
      )
        return
      event.preventDefault()
      props.onNavigate?.(props.href)
    })
    return (
      <li
        class={styles.item}
        data-interactive={props.href !== undefined || props.onSelect !== undefined ? '' : undefined}
        data-current={
          props.current && (props.href !== undefined || props.onSelect !== undefined)
            ? ''
            : undefined
        }
      >
        {leadingSlot.filled() ? <span class={styles.leading}>{leadingSlot()}</span> : null}
        <span class={styles.text}>
          {props.href !== undefined ? (
            <a
              class={classes(styles.title, styles.primary)}
              href={props.href}
              aria-current={props.current ? 'page' : undefined}
              onclick={($event: MouseEvent) => (props.onSelect?.(), route.value($event))}
            >
              {props.title}
            </a>
          ) : props.onSelect !== undefined ? (
            <button
              class={classes(styles.title, styles.primary)}
              type="button"
              aria-current={props.current ? 'true' : undefined}
              onclick={() => props.onSelect?.()}
            >
              {props.title}
            </button>
          ) : (
            <span class={styles.title}>{props.title}</span>
          )}
          {props.description !== undefined ? (
            <span class={styles.description}>{props.description}</span>
          ) : null}
        </span>
        {props.meta !== undefined ? <span class={styles.meta}>{props.meta}</span> : null}
        {trailingSlot.filled() ? <span class={styles.trailing}>{trailingSlot()}</span> : null}
      </li>
    )
  })
}
